/* ===== PATCH: 관리자 페이지 - 중개사 신청 관리 ===== */
.admin-page-panel{
	position: absolute;
	inset: var(--global-topbar-height) 0 0 0;
	z-index: 9990;
	display: none;
	background: #ffffff;
	color: #111827;
	overflow-y: scroll;
	overflow-x: hidden;
	scrollbar-gutter: stable;
	padding: 32px 32px 0;
}

.admin-page-head{
	position: relative;
	display: flex;
	align-items: center;
	justify-content: center;
	gap: 16px;
	width: 1180px;
	max-width: calc(100vw - 64px);
	margin: 0 auto 52px;
	text-align: center;
}

.admin-page-title{
	font-size: 34px;
	font-weight: 700;
	letter-spacing: -0.04em;
	line-height: 1.2;
	margin: 0;
	color: #111827;
}



.admin-refresh-btn{
	height: 38px;
	padding: 0 16px;
	border: 1px solid #1B6FA4;
	border-radius: 0;
	background: #1B6FA4;
	color: #fff;
	font-size: 14px;
	font-weight: 700;
	cursor: pointer;
	box-shadow: none;
}

.admin-page-head > .admin-refresh-btn{
	display: none;
}

.admin-application-list{
	display: flex;
	flex-direction: column;
	gap: 10px;
}

.admin-page-tabs{
	display: grid;
	grid-template-columns: repeat(6, minmax(0, 1fr));
	width: 1180px;
	max-width: calc(100vw - 64px);
	min-width: 0;
	margin: 0 auto 48px;
	border: 1px solid #e5e7eb;
	border-right: 0;
	background: #ffffff;
	box-sizing: border-box;
}

.admin-page-tab{
	width: 100%;
	min-width: 0;
	height: 56px;
	border: 0;
	border-right: 1px solid #e5e7eb;
	background: #ffffff;
	color: #111827;
	font: inherit;
	font-size: 15px;
	font-weight: 600;
	letter-spacing: -0.02em;
	cursor: pointer;
	box-shadow: none;
}

.admin-page-tab.active{
	background: #2563eb;
	color: #ffffff;
	font-weight: 600;
}

.admin-page-tab:focus,
.admin-page-tab:focus-visible{
	outline: none !important;
	box-shadow: none !important;
	transform: none !important;
}

.admin-page-tab-panel{
	display: none;
}

.admin-page-tab-panel.active{
	display: block;
	flex: 0 0 auto;
	width: 1180px;
	max-width: calc(100vw - 64px);
	margin: 0 auto;
}

.admin-application-card{
	display: grid;
	grid-template-columns: minmax(300px, 1.15fr) minmax(280px, 1.35fr) minmax(120px, 0.55fr) minmax(220px, auto);
	gap: 14px;
	align-items: center;
	padding: 16px;
	border: 1px solid #e5e7eb;
	border-radius: 0;
	background: #fff;
	box-shadow: none;
}

.admin-application-card.has-entitlement{
	grid-template-columns: minmax(300px, var(--admin-application-identity-track, 368px)) minmax(280px, 360px) repeat(3, minmax(240px, 1fr));
	justify-content: stretch;
	column-gap: 20px;
	row-gap: 14px;
}

.admin-application-entitlement{
	display: flex;
	flex-direction: column;
	align-items: flex-start;
	min-width: 0;
	gap: 0;
	text-align: left;
}

.admin-application-entitlement-row{
	max-width: 100%;
	color: #475569;
	overflow-wrap: anywhere;
	word-break: break-word;
}

.admin-application-entitlement-row:first-child{
	display: flex;
	align-items: center;
	min-height: 24px;
	font-size: 13px;
	font-weight: 800;
	letter-spacing: -0.1px;
}

.admin-application-entitlement-row + .admin-application-entitlement-row{
	margin-top: 6px;
}

.admin-application-office{
	min-width: 0;
	max-width: 100%;
	font-size: 14px;
	font-weight: 800;
	color: #111827;
	letter-spacing: -0.22px;
	line-height: 1.45;
	margin-bottom: 2px;
	overflow-wrap: anywhere;
	word-break: normal;
}

.admin-application-meta{
	font-size: 14px;
	font-weight: 600;
	color: #475569;
	line-height: 1.45;
	letter-spacing: -0.1px;
}

.admin-status-badge{
	display: inline-flex;
	align-items: center;
	justify-content: center;
	min-width: 92px;
	height: 24px;
	padding: 0 8px;
	border-radius: 0;
	font-size: 13px;
	font-weight: 800;
	letter-spacing: -0.1px;
	background: #f1f5f9;
	color: #475569;
}

.admin-status-badge.pending{
	background: #fff7ed;
	color: #ea580c;
}

.admin-status-badge.active{
	background: #eff6ff;
	color: #2563eb;
}

.admin-status-badge.rejected{
	background: #fef2f2;
	color: #dc2626;
}

.admin-application-actions{
	display: flex;
	align-items: center;
	justify-content: flex-end;
	gap: 8px;
	flex-wrap: wrap;
}

.admin-status-btn{
	height: 34px;
	padding: 0 12px;
	border: 1px solid #d1d5db;
	border-radius: 999px;
	background: #fff;
	color: #111827;
	font-size: 13px;
	font-weight: 700;
	cursor: pointer;
	box-shadow: none;
}

.admin-status-btn.approve{
	border-color: #2563eb;
	color: #2563eb;
}

.admin-status-btn.pending{
	border-color: #ea580c;
	color: #ea580c;
}

.admin-status-btn.reject{
	border-color: #dc2626;
	color: #dc2626;
}

.admin-status-btn.delete{
	border-color: #6b7280;
	color: #374151;
}

.admin-empty{
	padding: 28px 0;
	border: 0;
	border-top: 1px solid #e5e7eb;
	border-bottom: 1px solid #e5e7eb;
	background: #fff;
	text-align: center;
	font-size: 15px;
	font-weight: 700;
	color: #64748b;
}

