/* PATCH 2.670: MY 리얼제주 통합 탭 페이지 */
.my-suite-panel{
	position: fixed;
	inset: var(--global-topbar-height) 0 0 0;
	z-index: 120;
	display: none;
	background: #ffffff;
	color: #111827;
	overflow-y: scroll;
	overflow-x: hidden;
	scrollbar-gutter: stable;
	padding: 32px 32px 0;
}

body.my-suite-page-open .my-suite-panel,
.my-suite-panel[aria-hidden="false"]{
	display: block;
}

body.my-suite-page-open .sub-topbar,
body.my-suite-page-open .sidebar,
body.my-suite-page-open .resizer,
body.my-suite-page-open .map-wrap{
	display: none;
}

.my-suite-inner{
	width: 1180px;
	max-width: calc(100vw - 64px);
	min-height: calc(100vh - var(--global-topbar-height, 0px) - 122px);
	margin: 0 auto;
	display: flex;
	flex-direction: column;
}

.my-suite-tabs{
	display: flex;
	align-items: center;
	justify-content: center;
	gap: 6px;
	width: auto;
	min-width: 0;
	border: 0;
	background: transparent;
	box-sizing: border-box;
}

.my-suite-tab{
	position: relative;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: auto;
	min-width: 0;
	height: 34px;
	padding: 0 14px;
	border: 0;
	border-radius: 999px;
	background: transparent;
	color: #6b7280;
	font: inherit;
	font-size: 13.5px;
	font-weight: 600;
	letter-spacing: 0;
	line-height: 1;
	cursor: pointer;
	white-space: nowrap;
}

.my-suite-tab:hover{
	background: #f3f4f6;
	color: #111827;
	font-weight: 600;
}

.my-suite-tab.active{
	background: #2563eb;
	color: #ffffff;
	font-weight: 600;
}

.my-suite-tab.active::after{
	display: none;
}

.global-topbar-my-suite-tabs{
	position: absolute;
	left: 50%;
	top: 50%;
	z-index: 4;
	display: none;
	max-width: calc(100vw - 620px);
	padding: 0;
	overflow-x: auto;
	overflow-y: hidden;
	scrollbar-width: none;
	transform: translate(-50%, -50%);
}

.global-topbar-my-suite-tabs::-webkit-scrollbar{
	display: none;
	width: 0;
	height: 0;
}

body.my-suite-page-open .global-topbar-my-suite-tabs{
	display: flex;
}

