	grid-template-columns: repeat(3, minmax(0, 1fr));
	gap: 8px;
}

.deal-filter-grid{
	display: grid;
	grid-template-columns: repeat(4, minmax(0, 1fr));
	gap: 8px;
}

.extra-condition-filter-grid{
	grid-template-columns: repeat(3, minmax(0, 1fr));
}

.type-filter-tile,
.deal-filter-tile{
	position: relative;
	min-height: 36px;
	padding: 0;
	border-radius: 6px;
	background: transparent;
	cursor: pointer;
	user-select: none;
}

.type-filter-tile:hover,
.deal-filter-tile:hover{
	background: transparent;
}

.type-filter-tile input,
.deal-filter-tile input{
	position: absolute;
	width: 1px;
	height: 1px;
	margin: 0;
	opacity: 0;
	pointer-events: none;
}

.type-filter-tile span,
.deal-filter-tile span{
	display: flex;
	align-items: center;
	justify-content: center;
	width: 100%;
	min-height: 36px;
	padding: 0 8px;
	border: 1.25px solid transparent;
	border-radius: 6px;
	background: #f3f4f6;
	color: #73777d;
	font-family: var(--font-ui);
	font-size: 15px;
	font-weight: 600;
	line-height: 1.1;
	letter-spacing: 0;
	text-align: center;
	box-sizing: border-box;
	transition: background 0.14s ease, border-color 0.14s ease, color 0.14s ease;
}

.type-filter-tile input:checked + span,
.deal-filter-tile input:checked + span{
	border-color: #111827;
	background: #ffffff;
	color: #111827;
	font-weight: 700;
}

.type-filter-tile:hover span,
.deal-filter-tile:hover span{
	background: #eef0f3;
	color: #202124;
}

.type-filter-tile input:checked + span:hover,
.deal-filter-tile input:checked + span:hover{
	border-color: #111827;
	background: #f3f4f6;
	color: #111827;
}

.type-filter-menu .extra-filter-reset-row,
.deal-filter-menu .extra-filter-reset-row{
	margin-top: 0;
	padding-top: 12px;
	border-top: 1px solid #edf0f4;
}

.type-filter-menu .extra-filter-reset-btn,
.deal-filter-menu .extra-filter-reset-btn{
	min-height: 38px;
	font-size: 15px;
	font-weight: 600;
}

.extra-condition-filter-menu{
	width: 420px;
	min-width: 420px;
	max-width: min(420px, calc(100vw - 48px));
	padding: 22px 24px 24px;
	border-radius: 20px;
	gap: 16px;
}

.extra-condition-filter-menu .extra-filter-reset-row{
	width: 100%;
	margin-top: 16px;
	padding-top: 12px;
	border-top: 1px solid #edf0f4;
}

.extra-condition-filter-menu .extra-filter-reset-btn{
	min-height: 38px;
	font-size: 15px;
	font-weight: 600;
}

