	color: #111827;
	font-family: var(--font-ui);
	font-size: 18px;
	font-weight: 700;
	line-height: 1.2;
	letter-spacing: 0;
}

.area-filter-summary-row{
	display: flex;
	align-items: center;
	gap: 2px;
	width: 100%;
}

.area-filter-summary{
	margin-right: 0;
	color: #1764ff;
	font-family: var(--font-ui);
	font-size: 15px;
	font-weight: 700;
	line-height: 1.1;
	letter-spacing: 0;
	white-space: nowrap;
}

.area-filter-icon-btn,
.area-filter-unit-btn{
	border: 0;
	background: transparent;
	color: #1f2937;
	font-family: var(--font-ui);
	cursor: pointer;
}

.area-filter-icon-btn{
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 32px;
	height: 28px;
	border-radius: 50%;
	font-size: 15px;
	color: #6b7280;
}

.area-filter-icon-btn:hover{
	background: #f3f4f6;
	color: #111827;
}

.area-filter-unit-btn{
	display: inline-flex;
	align-items: center;
	justify-content: center;
	gap: 4px;
	min-width: 56px;
	height: 34px;
	padding: 0 12px;
	border: 1px solid #d9dee5;
	border-radius: 8px;
	background: #ffffff;
	font-size: 14px;
	font-weight: 500;
	box-shadow: 0 1px 2px rgba(15, 23, 42, 0.06);
}

.area-filter-unit-btn .fa-arrows-rotate{
	font-size: 13px;
	color: #4b5563;
	line-height: 1;
}

.area-filter-unit-btn:hover{
	background: #f8fafc;
}

.area-filter-manual-unit-btn{
	width: 48px;
	min-width: 48px;
	height: 36px;
	padding: 0;
	gap: 3px;
	font-size: 13px;
}

.area-filter-manual-unit-btn .fa-arrows-rotate{
	font-size: 12px;
}

.area-filter-reset-btn{
	display: none;
	margin-left: auto;
	width: 34px;
	height: 34px;
	border: 1px solid #d9dee5;
	background: #ffffff;
	color: #111827;
	font-size: 15px;
	box-shadow: 0 1px 2px rgba(15, 23, 42, 0.06);
}

.area-filter-reset-btn.is-visible{
	display: inline-flex;
}

.area-filter-reset-btn[hidden]{
	display: none !important;
}

.area-filter-slider-wrap{
	display: flex;
	flex-direction: column;
	gap: 12px;
	width: 100%;
	padding: 0;
	padding-top: 2px;
	box-sizing: border-box;
}

.area-filter-slider-rail{
	position: relative;
	width: 100%;
	height: 30px;
	cursor: pointer;
}

.area-filter-slider-rail::before{
	content: "";
	position: absolute;
	left: 0;
	right: 0;
	top: 14px;
	height: 4px;
	border-radius: 999px;
	background: #dfe3e7;
}

.area-filter-slider-fill{
	position: absolute;
	top: 14px;
	height: 4px;
	border-radius: 999px;
	background: #1764ff;
	pointer-events: none;
}

.area-filter-range{
	position: absolute;
	left: 0;
	top: 0;
	width: 100%;
	height: 30px;
	margin: 0;
	background: transparent;
	pointer-events: none;
	appearance: none;
	-webkit-appearance: none;
}

.area-filter-range::-webkit-slider-runnable-track{
	height: 30px;
	background: transparent;
}

.area-filter-range::-webkit-slider-thumb{
	width: 26px;
	height: 26px;
	margin-top: 2px;
	border: 1.4px solid #1764ff;
	border-radius: 50%;
	background: #ffffff;
	box-shadow: 0 2px 6px rgba(15, 23, 42, 0.15);
	cursor: grab;
	pointer-events: auto;
	-webkit-appearance: none;
}

.area-filter-range:active::-webkit-slider-thumb,
.area-filter-range.is-dragging::-webkit-slider-thumb{
	cursor: grabbing;
}

.area-filter-range::-moz-range-track{
	height: 30px;
	background: transparent;
}

.area-filter-range::-moz-range-thumb{
	width: 26px;
	height: 26px;
	border: 1.4px solid #1764ff;
	border-radius: 50%;
	background: #ffffff;
	box-shadow: 0 2px 6px rgba(15, 23, 42, 0.15);
	cursor: grab;
	pointer-events: auto;
}

.area-filter-range:active::-moz-range-thumb,
.area-filter-range.is-dragging::-moz-range-thumb{
	cursor: grabbing;
}

.area-filter-scale{
	position: relative;
	display: block;
	height: 18px;
	color: #111827;
	font-family: var(--font-ui);
	font-size: 14px;
	font-weight: 600;
	line-height: 1;
	letter-spacing: 0;
	text-align: center;
}

.area-filter-scale span{
	position: absolute;
	top: 0;
	width: 56px;
	margin-left: -28px;
	transform: none;
	text-align: center;
	white-space: nowrap;
}

.area-filter-scale span:first-child{
	width: 56px;
	margin-left: 0;
	text-align: left;
}

.area-filter-scale span:last-child{
	width: 56px;
	margin-left: -56px;
	text-align: right;
}

.area-filter-target-options{
	display: flex;
	flex-direction: column;
	align-items: flex-start;
	gap: 12px;
}

.area-filter-exclusive-option{
	display: inline-flex;
	align-items: center;
	gap: 10px;
	width: fit-content;
	color: #3f4652;
	font-family: var(--font-ui);
	font-size: 15px;
	font-weight: 600;
	line-height: 1.2;
	letter-spacing: 0;
	cursor: pointer;
	user-select: none;
}

.area-filter-exclusive-option input{
	width: 22px;
	height: 22px;
	margin: 0;
	accent-color: #111827;
	cursor: pointer;
	flex: 0 0 22px;
}

.area-filter-manual-modal{
	position: fixed;
	top: 0;
	right: 0;
	bottom: 0;
	left: 0;
	inset: 0;
	width: 100vw;
	height: 100vh;
	display: none;
	align-items: center;
	justify-content: center;
	z-index: 70000;
}

.area-filter-manual-modal.open{
	display: flex;
}

.area-filter-manual-backdrop{
	position: absolute;
	inset: 0;
	background: rgba(0, 0, 0, 0.45);
}

.area-filter-manual-dialog{
	position: relative;
	width: min(600px, calc(100vw - 56px));
	margin: 0;
	padding: 24px 22px 22px;
	border: 0;
	border-radius: 18px;
	background: #ffffff;
	box-shadow: 0 24px 60px rgba(15, 23, 42, 0.24);
}

.area-filter-manual-head{
	display: grid;
	grid-template-columns: 48px 1fr 48px;
	align-items: center;
	gap: 12px;
	margin-bottom: 22px;
}

.area-filter-manual-head h3{
	margin: 0;
	color: #111827;
	font-family: var(--font-ui);
	font-size: 21px;
	font-weight: 700;
	line-height: 1.1;
	text-align: center;
	letter-spacing: 0;
}

.area-filter-manual-close{
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 40px;
	height: 40px;
	border: 0;
	border-radius: 50%;
	background: transparent;
	color: #111827;
	font-size: 26px;
	cursor: pointer;
}

.area-filter-manual-close:hover{
	background: #f3f4f6;
}

.area-filter-manual-fields{
	display: grid;
	grid-template-columns: minmax(0, 1fr) 26px minmax(0, 1fr);
	align-items: center;
	gap: 12px;
	margin-bottom: 8px;
}

.area-filter-manual-field{
	display: grid;
	grid-template-columns: minmax(0, 1fr) 28px 24px;
	align-items: center;
	column-gap: 2px;
	height: 54px;
	padding: 0 12px 0 16px;
	border: 1px solid #d8dde4;
	border-radius: 8px;
	background: #ffffff;
}

.area-filter-manual-field.is-invalid{
	border-color: #ff3030;
	border-width: 2px;
}

.area-filter-manual-field input{
	width: 100%;
	min-width: 0;
	border: 0;
	outline: 0;
	background: transparent;
	color: #111827;
	font-family: var(--font-ui);
	font-size: 18px;
	font-weight: 700;
	letter-spacing: 0;
}

.area-filter-manual-field.is-invalid input{
	color: #ff3030;
}

.area-filter-manual-field input::placeholder{
	color: #c2c7cf;
	font-weight: 600;
	opacity: 1;
}

.area-filter-manual-field input[type="number"]{
	appearance: textfield;
	-moz-appearance: textfield;
}

.area-filter-manual-field input[type="number"]::-webkit-outer-spin-button,
.area-filter-manual-field input[type="number"]::-webkit-inner-spin-button{
	margin: 0;
	-webkit-appearance: none;
}

.area-filter-manual-clear{
	display: inline-flex;
	justify-self: end;
	align-items: center;
	justify-content: center;
	width: 24px;
	height: 24px;
	border: 0;
	border-radius: 50%;
	background: #9ca3af;
	color: #ffffff;
	font-size: 14px;
	line-height: 1;
	cursor: pointer;
	opacity: 0;
	pointer-events: none;
	visibility: hidden;
}

.area-filter-manual-clear.is-visible{
	opacity: 1;
	pointer-events: auto;
	visibility: visible;
}

.area-filter-manual-unit{
	justify-self: end;
	color: #111827;
	font-family: var(--font-ui);
	font-size: 18px;
	font-weight: 700;
	line-height: 1;
}

.area-filter-manual-separator{
	color: #111827;
	font-family: var(--font-ui);
	font-size: 22px;
	font-weight: 700;
	text-align: center;
}

.area-filter-manual-errors{
	display: grid;
	grid-template-columns: minmax(0, 1fr) 26px minmax(0, 1fr);
	align-items: start;
	gap: 12px;
	min-height: 18px;
	margin-bottom: 12px;
	color: #ff3030;
	font-family: var(--font-ui);
	font-size: 14px;
	font-weight: 600;
	line-height: 1.2;
	letter-spacing: 0;
}

.area-filter-manual-errors span{
	display: block;
	min-height: 18px;
}

.area-filter-manual-apply{
	display: flex;
	align-items: center;
	justify-content: center;
	width: 100%;
	height: 58px;
	border: 0;
	border-radius: 8px;
	background: #1764ff;
	color: #ffffff;
	font-family: var(--font-ui);
	font-size: 18px;
	font-weight: 700;
	letter-spacing: 0;
	cursor: pointer;
}

.area-filter-manual-apply:hover{
	background: #0f55df;
}

.area-filter-manual-apply:disabled{
	background: #d9dce1;
	color: #a7adb7;
	cursor: not-allowed;
}

.area-filter-manual-apply:disabled:hover{
	background: #d9dce1;
}

