	margin-bottom: 0;
}

.payment-addon-shop-grid{
	display: grid;
	grid-template-columns: repeat(2, minmax(0, 1fr));
	gap: 12px;
}

.payment-addon-card{
	display: flex;
	min-width: 0;
	padding: 22px;
	flex-direction: column;
	border: 1px solid #e5e7eb;
	border-radius: 8px;
	background: #ffffff;
	box-sizing: border-box;
}

.payment-addon-card-head{
	display: flex;
	align-items: flex-start;
	gap: 12px;
}

.payment-addon-card-number{
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 36px;
	height: 36px;
	flex: 0 0 36px;
	border-radius: 8px;
	background: #eff6ff;
	color: #2563eb;
	font-size: 12px;
	font-weight: 800;
}

.payment-addon-card-head > div{
