	line-height: 1.5;
}

.payment-addon-option-list{
	display: grid;
	grid-template-columns: repeat(auto-fit, minmax(104px, 1fr));
	gap: 8px;
	margin-top: 20px;
}

.payment-addon-option{
	display: grid;
	gap: 4px;
	min-width: 0;
	padding: 11px 10px;
