.payment-addon-option:hover{
	border-color: #bfdbfe;
	background: #f8fbff;
}

.payment-addon-option.is-selected{
	border-color: #2563eb;
	background: #eff6ff;
	color: #1d4ed8;
}

.payment-addon-option:focus-visible{
	outline: 2px solid #93c5fd;
	outline-offset: 2px;
}

.payment-addon-option span{
	font-size: 13px;
	font-weight: 800;
	line-height: 1.3;
}

.payment-addon-option strong{
	color: inherit;
	font-size: 11px;
	font-weight: 700;
	line-height: 1.3;
	white-space: nowrap;
}

.payment-addon-card-footer{
	display: flex;
	align-items: flex-end;
	justify-content: space-between;
	gap: 14px;
	margin-top: auto;
	padding-top: 20px;
}

.payment-addon-selection{
	display: grid;
	gap: 4px;
	min-width: 0;
}

.payment-addon-selection span{
	color: #94a3b8;
	font-size: 11px;
	font-weight: 600;
}

.payment-addon-selection strong{
	overflow: hidden;
	color: #111827;
	font-size: 13px;
	font-weight: 750;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.payment-addon-buy-btn{
	display: inline-flex;
	align-items: center;
	justify-content: center;
	min-width: 102px;
	height: 40px;
	padding: 0 16px;
