	border: 1px solid #2563eb;
	border-radius: 8px;
	background: #2563eb;
	color: #ffffff;
	font-size: 13px;
	font-weight: 700;
	cursor: pointer;
}

.payment-addon-buy-btn:hover:not(:disabled){
	background: #1d4ed8;
	border-color: #1d4ed8;
}

.payment-addon-buy-btn:focus-visible{
	outline: 2px solid #93c5fd;
	outline-offset: 2px;
}

.payment-addon-buy-btn:disabled{
	border-color: #e5e7eb;
	background: #f1f5f9;
	color: #94a3b8;
	cursor: not-allowed;
}

